import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename
import hashlib
import time

app = Flask(__name__)
UPLOAD_DIR = '/tmp/conversions'
ALLOWED_EXTENSIONS = {'doc', 'docx', 'odt', 'rtf', 'txt', 'html'}

os.makedirs(UPLOAD_DIR, exist_ok=True)

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def sanitize_metadata(metadata_str):
    """Remove potentially dangerous characters from metadata fields."""
    # Basic sanitization - strip null bytes and control chars
    cleaned = metadata_str.replace('\x00', '').strip()
    # Limit length
    return cleaned[:256]

@app.route('/api/v1/convert', methods=['POST'])
def convert_document():
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    file = request.files['file']
    if file.filename == '':
        return jsonify({'error': 'Empty filename'}), 400

    if not allowed_file(file.filename):
        return jsonify({'error': 'File type not allowed'}), 400

    # Get conversion parameters
    output_format = request.form.get('format', 'pdf')
    author = request.form.get('author', 'Unknown')
    title = request.form.get('title', '')

    # Generate unique output path
    timestamp = str(time.time())
    file_hash = hashlib.md5((file.filename + timestamp).encode()).hexdigest()
    input_filename = secure_filename(file.filename)
    input_path = os.path.join(UPLOAD_DIR, f"{file_hash}_{input_filename}")
    output_path = os.path.join(UPLOAD_DIR, f"{file_hash}_output.{output_format}")

    file.save(input_path)

    try:
        # Build LibreOffice conversion command
        # Use macro to set document properties before conversion
        sanitized_title = sanitize_metadata(title)
        sanitized_author = sanitize_metadata(author)

        # Construct the conversion with metadata embedding
        # The exiftool post-processing sets PDF metadata
        convert_cmd = [
            'libreoffice', '--headless', '--convert-to', output_format,
            '--outdir', UPLOAD_DIR, input_path
        ]

        result = subprocess.run(convert_cmd, capture_output=True, timeout=30,
                              cwd=UPLOAD_DIR)

        if result.returncode != 0:
            return jsonify({'error': 'Conversion failed', 
                          'details': result.stderr.decode()[:200]}), 500

        # Rename LibreOffice output to our expected path
        lo_output = os.path.join(UPLOAD_DIR, 
                                f"{file_hash}_{os.path.splitext(input_filename)[0]}.{output_format}")
        if os.path.exists(lo_output):
            os.rename(lo_output, output_path)

        # Post-process: embed metadata using exiftool
        if os.path.exists(output_path) and output_format == 'pdf':
            meta_cmd = f'exiftool -Title="{sanitized_title}" -Author="{sanitized_author}" -overwrite_original "{output_path}"'
            subprocess.run(meta_cmd, shell=True, timeout=10, cwd=UPLOAD_DIR)

        if not os.path.exists(output_path):
            return jsonify({'error': 'Output file not generated'}), 500

        return send_file(output_path, as_attachment=True,
                        download_name=f"converted.{output_format}")

    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Conversion timed out'}), 504
    finally:
        # Cleanup
        for f in [input_path, output_path]:
            if os.path.exists(f):
                try:
                    os.unlink(f)
                except OSError:
                    pass

@app.route('/api/v1/formats', methods=['GET'])
def list_formats():
    return jsonify({
        'input': list(ALLOWED_EXTENSIONS),
        'output': ['pdf', 'docx', 'odt', 'html', 'txt']
    })

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.1.4'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
